import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum LessonType {
  Lecture = "Лекция",
  Practice = "Практика",
  Lab = "Лабораторная",
  Consultation = "Консультация"
}

export interface Lesson {
  id: string;
  timeStart: string;
  timeEnd: string;
  subject: string;
  type: string;
  location: string;
  teacher: string;
  groups?: string;
}

export interface DaySchedule {
  dayName: string;
  lessons: Lesson[];
}

export interface WeekData {
  [key: number]: DaySchedule[];
}

import React from 'react';
import { Lesson } from '../types';

interface ClassCardProps {
  lesson: Lesson;
}

const ClassCard: React.FC<ClassCardProps> = ({ lesson }) => {
  // Determine badge color based on lesson type
  const getTypeColor = (type: string) => {
    const lowerType = type.toLowerCase();
    if (lowerType.includes('лекц')) return 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300';
    if (lowerType.includes('прак')) return 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300';
    if (lowerType.includes('лаб')) return 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300';
    return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg p-4 shadow-sm border border-slate-100 dark:border-slate-700 hover:shadow-md transition-shadow duration-200 h-full flex flex-col justify-between">
      <div>
        <div className="flex justify-between items-start mb-2">
          <div className="flex flex-col">
            <span className="text-lg font-bold text-slate-900 dark:text-white leading-tight">
              {lesson.timeStart}
            </span>
            <span className="text-xs text-slate-400 dark:text-slate-500 font-medium">
              - {lesson.timeEnd}
            </span>
          </div>
          <span className={`px-2 py-1 rounded-md text-[10px] uppercase font-bold tracking-wide ${getTypeColor(lesson.type)}`}>
            {lesson.type.replace(/занятия|работа/gi, '').trim()}
          </span>
        </div>

        <h3 className="font-semibold text-slate-800 dark:text-slate-100 mb-3 text-sm leading-snug min-h-[2.5rem]">
          {lesson.subject}
        </h3>
      </div>

      <div className="space-y-2 mt-2 pt-3 border-t border-slate-100 dark:border-slate-700">
        <div className="flex items-start gap-2">
          <svg className="w-4 h-4 text-slate-400 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          <span className="text-xs text-slate-600 dark:text-slate-300 font-medium">{lesson.location}</span>
        </div>

        <div className="flex items-start gap-2">
          <svg className="w-4 h-4 text-slate-400 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
          </svg>
          <span className="text-xs text-slate-600 dark:text-slate-300">{lesson.teacher}</span>
        </div>

        {lesson.groups && (
          <div className="flex items-start gap-2">
             <svg className="w-4 h-4 text-slate-400 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
