export default ClassCard;

import React from 'react';
import { DaySchedule } from '../types';
import ClassCard from './ClassCard';

interface DayColumnProps {
  daySchedule: DaySchedule;
}

const DayColumn: React.FC<DayColumnProps> = ({ daySchedule }) => {
  return (
    <div className="flex flex-col min-w-[300px] md:min-w-0">
      <div className="mb-4 flex items-center gap-2">
        <h2 className="text-xl font-bold text-slate-800 dark:text-white">
          {daySchedule.dayName}
        </h2>
        <span className="text-xs font-medium text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
            {daySchedule.lessons.length} {daySchedule.lessons.length === 1 ? 'пара' : daySchedule.lessons.length > 4 ? 'пар' : 'пары'}
        </span>
      </div>

      <div className="flex flex-col gap-4">
        {daySchedule.lessons.map((lesson) => (
          <ClassCard key={lesson.id} lesson={lesson} />
        ))}
        {daySchedule.lessons.length === 0 && (
          <div className="p-4 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-lg text-center text-slate-400">
            Нет пар
          </div>
